    'Yoast > Workouts' => 'Yoast > Workouts',
    'Yoast > Courses' => 'Yoast > Courses',
    'Yoast > Academy' => 'Yoast > Academy',
    'Yoast > Premium licenses screens' => 'Yoast > Premium licenses screens',
